WITH m AS (SELECT end_id AS node_id, end_name AS node_name, end_of AS of FROM "@receipt-triples:transform_rows" WHERE end_type = 'Merchant' AND end_id IS NOT NULL AND end_id <> '') SELECT node_id, node_id AS __corvic_surrogate_id, 'Merchant' AS node_type, min(node_name) AS name, min(json_extract_string(of, '$.address')) AS address, min(json_extract_string(of, '$.phone')) AS phone, count(*) AS mention_count FROM m GROUP BY node_id